import 'package:flutter/foundation.dart';
import 'package:razorpay_flutter/razorpay_flutter.dart';
class PaymentService { final Razorpay _razorpay=Razorpay(); VoidCallback? onSuccess,onFailure; void initialize({required VoidCallback success,required VoidCallback failure}){onSuccess=success;onFailure=failure;_razorpay.on(Razorpay.EVENT_PAYMENT_SUCCESS,(_)=>onSuccess?.call());_razorpay.on(Razorpay.EVENT_PAYMENT_ERROR,(_)=>onFailure?.call());} void open({required double amount,required String phone,required String email}){if(kIsWeb)throw UnsupportedError('Razorpay Flutter plugin requires Android/iOS configuration');_razorpay.open({'key':'REPLACE_WITH_RAZORPAY_TEST_KEY','amount':(amount*100).round(),'name':'FreshCart','description':'Grocery order','prefill':{'contact':phone,'email':email},'theme':{'color':'#2E7D32'}});} void dispose(){_razorpay.clear();}}
